import json
import re
from html.parser import HTMLParser

from lfx.custom.custom_component.component import Component
from lfx.io import DropdownInput, MessageTextInput, MultilineInput, Output

INTERACTIVE_TAGS = {
    "a", "button", "input", "textarea", "select", "option", "form", "label",
    "fieldset", "details", "summary", "dialog", "audio", "video",
}

KEEP_ATTRS = {
    "id", "name", "type", "class", "role", "title", "alt", "href", "for",
    "value", "placeholder", "checked", "disabled", "selected", "required",
    "readonly", "maxlength", "multiple", "autocomplete", "tabindex",
    "aria-label", "aria-labelledby", "aria-describedby", "aria-expanded",
    "aria-selected", "aria-checked", "aria-pressed", "aria-hidden",
}

DATA_ATTR_RE = re.compile(r"^data-", re.IGNORECASE)

MAX_HTML_CHARS = 500000
MAX_ELEMENTS = 80
MAX_TEXT_CHARS = 200

SKIP_TAGS = {"script", "style", "svg", "template", "noscript", "head"}


class _DomParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.elements = []
        self._skip_depth = 0
        self._open = []

    def _attrs(self, attrs):
        kept = {}
        for key, value in attrs:
            if key in KEEP_ATTRS or DATA_ATTR_RE.match(key):
                kept[key] = (value or "").strip()[:200]
        return kept

    def handle_starttag(self, tag, attrs):
        if tag in SKIP_TAGS:
            self._skip_depth += 1
            return
        if self._skip_depth:
            return
        if tag in INTERACTIVE_TAGS:
            el = {"tag": tag, "attributes": self._attrs(attrs), "text": ""}
            self.elements.append(el)
            if tag != "input":
                self._open.append(el)
        else:
            self._open.append(None)

    def handle_startendtag(self, tag, attrs):
        if tag in SKIP_TAGS or self._skip_depth:
            return
        if tag in INTERACTIVE_TAGS:
            self.elements.append(
                {"tag": tag, "attributes": self._attrs(attrs), "text": ""}
            )

    def handle_endtag(self, tag):
        if tag in SKIP_TAGS:
            if self._skip_depth:
                self._skip_depth -= 1
            return
        if self._skip_depth:
            return
        if self._open:
            self._open.pop()

    def handle_data(self, data):
        if self._skip_depth:
            return
        text = " ".join(data.split())
        if not text:
            return
        for el in reversed(self._open):
            if el is not None:
                el["text"] = (el["text"] + " " + text).strip()[:MAX_TEXT_CHARS]
                break


class DomProcessorComponent(Component):
    display_name = "DOM Processor"
    description = (
        "Normalizes raw HTML/DOM, extracts interactive elements, and preserves "
        "locator-friendly attributes before LLM analysis."
    )
    icon = "scan"
    name = "DomProcessor"

    inputs = [
        MultilineInput(
            name="html",
            display_name="HTML Content",
            info="Raw HTML or DOM snippet to analyze.",
        ),
        MessageTextInput(
            name="page_url",
            display_name="Page URL",
            info="Optional source URL of the page.",
            required=False,
        ),
        DropdownInput(
            name="framework",
            display_name="Framework",
            info="Target test automation framework.",
            options=["Selenium", "Playwright", "Cypress"],
            value="Playwright",
        ),
        DropdownInput(
            name="language",
            display_name="Language",
            info="Target programming language.",
            options=["Java", "Python", "JavaScript", "TypeScript", "C#"],
            value="TypeScript",
        ),
        MessageTextInput(
            name="focus_element",
            display_name="Focus Element",
            info="Optional element label or selector to prioritize.",
            required=False,
        ),
    ]

    outputs = [
        Output(name="payload", display_name="Payload", method="process_dom"),
    ]

    def process_dom(self) -> str:
        warnings = []
        raw = (self.html or "").strip()
        if not raw:
            raise ValueError("No HTML content provided.")

        framework = self.framework
        language = self.language
        page_url = self.page_url or ""
        focus_element = self.focus_element or ""
        elements = None
        source_note = None

        # API envelope support: the backend sends a single JSON message like
        # {"framework": "...", "language": "...", "elementList": "...",
        #  "warnings": [...], "sourceNote": "..."}.
        # Parsing it here avoids LangFlow tweaks, which drop edge-connected inputs.
        stripped = raw.strip()
        if stripped.startswith("{") and stripped.endswith("}"):
            try:
                envelope = json.loads(stripped)
                if not isinstance(envelope, dict):
                    raise ValueError("Envelope must be a JSON object.")
                framework = str(envelope.get("framework") or framework)
                language = str(envelope.get("language") or language)
                page_url = str(envelope.get("pageUrl") or envelope.get("page_url") or page_url)
                focus_element = str(envelope.get("focusElement") or envelope.get("focus_element") or focus_element)
                warnings.extend(str(w) for w in (envelope.get("warnings") or []) if w)
                source_note = envelope.get("sourceNote") or None
                if envelope.get("html"):
                    raw = str(envelope.get("html") or "")
                elif envelope.get("elementList") is not None:
                    element_list = envelope.get("elementList")
                    if isinstance(element_list, str):
                        elements = [line.strip() for line in element_list.splitlines() if line.strip()]
                    elif isinstance(element_list, list):
                        elements = [str(item) for item in element_list]
                    else:
                        raise ValueError("elementList must be a string or a list.")
                    if not elements:
                        raise ValueError("elementList is empty.")
            except (json.JSONDecodeError, ValueError, TypeError):
                pass  # not a usable envelope, treat the input as raw HTML

        if elements is None:
            if len(raw) > MAX_HTML_CHARS:
                raw = raw[:MAX_HTML_CHARS]
                warnings.append("HTML input truncated to 500000 characters.")

            parser = _DomParser()
            parser.feed(raw)
            parser.close()

            elements = parser.elements
            if not elements:
                raise ValueError(
                    "No interactive elements found in the supplied HTML. "
                    f"Received {len(raw)} chars: {raw[:300]!r}"
                )

        if len(elements) > MAX_ELEMENTS:
            warnings.append("Only the first 80 interactive elements were analyzed.")
            elements = elements[:MAX_ELEMENTS]

        payload = {
            "framework": framework,
            "language": language,
            "page_url": page_url,
            "focus_element": focus_element,
            "elements": elements,
            "warnings": warnings,
            "source_note": source_note or "Normalized by the flow DOM Processor.",
        }
        self.status = f"Prepared {len(elements)} interactive elements."
        return json.dumps(payload)
